def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the color used for complete separator lines.
    row_lines = {}
    col_lines = {}
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            row_lines.setdefault(row[0], []).append(r)
    for c in range(w):
        v = grid[0][c]
        if v != 0 and all(grid[r][c] == v for r in range(h)):
            col_lines.setdefault(v, []).append(c)
    div = max(set(row_lines) & set(col_lines),
              key=lambda x: len(row_lines[x]) + len(col_lines[x]))

    rs, cs = row_lines[div], col_lines[div]
    row_bounds = [-1] + rs + [h]
    col_bounds = [-1] + cs + [w]
    bands = [(row_bounds[i] + 1, row_bounds[i + 1])
             for i in range(len(row_bounds) - 1)]
    panels = [(col_bounds[i] + 1, col_bounds[i + 1])
              for i in range(len(col_bounds) - 1)]

    # Identify the repeated seed colors in the leftmost panel of each band.
    seeds = []
    for r0, r1 in bands:
        counts = {}
        for r in range(r0, r1):
            for c in range(panels[0][0], panels[0][1]):
                v = grid[r][c]
                if v and v != div:
                    counts[v] = counts.get(v, 0) + 1
        seeds.append(max(counts, key=counts.get))

    # The template is the non-divider color with the greatest total count.
    counts = {}
    for row in grid:
        for v in row:
            if v and v != div:
                counts[v] = counts.get(v, 0) + 1
    template_color = max(counts, key=counts.get)

    # Record its shape relative to the panel containing it.
    shape = None
    for r0, r1 in bands:
        for c0, c1 in panels:
            pts = [(r-r0, c-c0) for r in range(r0, r1)
                   for c in range(c0, c1) if grid[r][c] == template_color]
            if pts:
                shape = pts
                break
        if shape:
            break

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(bands):
        for c0, c1 in panels:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in shape:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = seeds[i]
    return out
